   <div className="flex-1 overflow-y-auto px-5 py-4">{!cart.length?<div className="grid h-full content-center justify-items-center text-center"><span className="text-5xl">🧶</span><h3 className="mt-4 font-display text-2xl">Your bag is waiting</h3><p className="mt-2 text-sm text-stone-500">Find something handmade just for you.</p><button onClick={()=>{setCartOpen(false);document.getElementById('shop')?.scrollIntoView({behavior:'smooth'})}} className="mt-5 rounded-full bg-thread-plum px-6 py-3 text-sm font-semibold text-white">Start shopping</button></div>:<div className="space-y-4">{cart.map(i=><article key={i.id} className="flex gap-4 rounded-2xl border border-thread-sand bg-white p-3"><img src={i.image} alt={i.name} className="h-24 w-20 rounded-xl bg-thread-blush object-cover"/><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><h3 className="font-semibold">{i.name}</h3><p className="mt-1 text-sm font-semibold text-thread-plum">{money(i.price)}</p></div><button onClick={()=>removeFromCart(i.id)} className="text-xl text-stone-400 hover:text-red-500" aria-label={`Remove ${i.name}`}>×</button></div><div className="mt-3 inline-flex items-center rounded-full border border-thread-sand"><button onClick={()=>decreaseQuantity(i.id)} className="h-8 w-9 text-lg">−</button><span className="w-7 text-center text-sm font-semibold">{i.quantity}</span><button disabled={i.quantity>=Number(i.stock??99)} onClick={()=>increaseQuantity(i.id)} className="h-8 w-9 text-lg disabled:text-stone-300">+</button></div></div></article>)}</div>}</div>
